<?php
namespace App\Http\Controllers\Admin;
use App\Actions\Withdrawals\TransitionWithdrawal;use App\Http\Controllers\Controller;use App\Models\WithdrawalClaim;use Illuminate\Http\RedirectResponse;use Illuminate\Http\Request;use Illuminate\View\View;
class WithdrawalController extends Controller
{public function index(Request $r):View{abort_unless($r->user()->can('withdrawals.process'),403);return view('admin.withdrawals.index',['withdrawals'=>WithdrawalClaim::with('mitra')->latest()->paginate(25)]);}public function show(Request $r,WithdrawalClaim $withdrawal):View{abort_unless($r->user()->can('withdrawals.process'),403);return view('admin.withdrawals.show',['withdrawal'=>$withdrawal->load(['mitra','transfer','journals.lines'])]);}public function transition(Request $r,WithdrawalClaim $withdrawal,TransitionWithdrawal $action):RedirectResponse{abort_unless($r->user()->can('withdrawals.process'),403);$data=$r->validate(['transition'=>'required|in:review,approve,reject,processing,paid','reason'=>'nullable|string|max:1000','transfer_reference'=>'nullable|string|max:191','transferred_at'=>'nullable|date','notes'=>'nullable|string|max:1000']);$action->execute($withdrawal,$data['transition'],$r->user(),$data);return back()->with('status','Status withdrawal diperbarui.');}}
